<?php
namespace App\Controllers;
use App\Core\Controller; use App\Core\Database;
class DashboardController extends Controller { public function index(): void { $db=Database::connection(); $stats=['clients'=>(int)$db->query('SELECT COUNT(*) FROM clients')->fetchColumn(),'packages'=>(int)$db->query("SELECT COUNT(*) FROM packages WHERE status='Activo'")->fetchColumn(),'reservations'=>(int)$db->query("SELECT COUNT(*) FROM reservations WHERE status IN ('Pendiente','Confirmada')")->fetchColumn(),'revenue'=>(float)$db->query('SELECT COALESCE(SUM(amount),0) FROM payments')->fetchColumn(),'pending'=>(float)$db->query("SELECT COALESCE(SUM(total_amount),0)-COALESCE((SELECT SUM(amount) FROM payments),0) FROM reservations WHERE status!='Cancelada'")->fetchColumn()]; $recent=$db->query('SELECT r.code,c.name client_name,p.name package_name,r.travel_date,r.status,r.total_amount FROM reservations r JOIN clients c ON c.id=r.client_id JOIN packages p ON p.id=r.package_id ORDER BY r.id DESC LIMIT 6')->fetchAll(); $this->render('dashboard/index',compact('stats','recent')); } }
